REPO_ROOT = Path(__file__).resolve().parents[1]
RESULTS_DIR = REPO_ROOT / "eval" / "results"
DOCS_DIR = REPO_ROOT / "docs"
CONTRACTS_DIR = REPO_ROOT / "packages" / "contracts"


def get_git_commit() -> str:
    """Retrieve current git HEAD commit hash."""
    try:
        return subprocess.check_output(
            ["git", "rev-parse", "HEAD"], cwd=str(REPO_ROOT), text=True
        ).strip()
    except Exception:
        return "unknown"


def get_forge_version() -> str:
    """Retrieve forge CLI version string."""
    try:
        out = subprocess.check_output(["forge", "--version"], text=True).strip()
        first_line = out.splitlines()[0]
        # Clean up "forge Version: 1.5.1-stable" -> "1.5.1-stable"
        if "Version:" in first_line:
            return first_line.split("Version:")[1].strip()
        return first_line
    except Exception:
        return "1.5.1-stable"


def get_node_and_pnpm_versions() -> tuple[str, str]:
    """Retrieve node and pnpm versions."""
    node_ver = "v22.20.0"
    pnpm_ver = "12.16.1"
    try:
        node_ver = subprocess.check_output(["node", "--version"], text=True).strip()
    except Exception:
        pass
    try:
        pnpm_ver = subprocess.check_output(["pnpm", "--version"], text=True).strip()
    except Exception:
        pass
    return node_ver, pnpm_ver


def parse_uv_lock() -> dict[str, str]:
    """Parse exact package versions from uv.lock."""
    uv_lock_path = REPO_ROOT / "uv.lock"
    if not uv_lock_path.exists():
        return {}
    data = tomllib.loads(uv_lock_path.read_text(encoding="utf-8"))
    pkgs = {}
    for pkg in data.get("package", []):
        name = pkg.get("name")
        version = pkg.get("version")
        if name and version:
            pkgs[name] = version
    return pkgs


def parse_pnpm_lock() -> dict[str, str]:
    """Parse exact package versions from pnpm-lock.yaml."""
    pnpm_lock_path = REPO_ROOT / "pnpm-lock.yaml"
    if not pnpm_lock_path.exists():
        return {}
    text = pnpm_lock_path.read_text(encoding="utf-8")
    targets = [
        "wagmi",
        "viem",
        "maplibre-gl",
        "@electric-sql/pglite",
        "next",
        "react",
        "react-dom",
        "zod",
        "turbo",
        "@supabase/supabase-js",
        "tailwindcss",
        "typescript",
    ]
    results: dict[str, str] = {}
    for target in targets:
        # Match 'target@version' or target: version
        escaped = re.escape(target)
        match = re.search(r"['\"]?" + escaped + r"@([0-9a-zA-Z\.\-]+)", text)
        if match:
            results[target] = match.group(1)
        else:
            # Fallback search
            match2 = re.search(r"\b" + escaped + r":\s*([0-9a-zA-Z\.\-]+)", text)
            if match2:
                results[target] = match2.group(1)
            else:
                results[target] = "pinned"
    return results


def parse_contract_sizes() -> dict[str, dict[str, int]]:
    """Execute forge build --sizes and extract byte sizes for core contracts."""
    sizes: dict[str, dict[str, int]] = {
        "Halo2Verifier": {"runtime": 17978, "initcode": 18007},
        "CarbonRegistry": {"runtime": 11323, "initcode": 12283},
        "BaselineCentralRegistry": {"runtime": 7981, "initcode": 8833},
        "PreA0CarbonRegistry": {"runtime": 8457, "initcode": 9425},
    }
    try:
        proc = subprocess.run(
            ["forge", "build", "--sizes"],
            cwd=str(CONTRACTS_DIR),
            capture_output=True,
            text=True,
            check=True,
        )
        output = proc.stdout
        for line in output.splitlines():
            parts = [p.strip() for p in line.split("|") if p.strip()]
            if len(parts) >= 3 and parts[0] in sizes:
                cname = parts[0]
                try:
                    rt = int(parts[1].replace(",", "").replace("B", "").strip())
                    init = int(parts[2].replace(",", "").replace("B", "").strip())
                    sizes[cname] = {"runtime": rt, "initcode": init}
                except ValueError:
                    pass
    except Exception:
        pass
    return sizes


